# -*- coding: utf-8 -*-
from deep1 import D,lesson,S
# ================= CSDL / SQL =================
lesson('sql_group','SQL: GROUP BY, HAVING và thứ tự xử lí',['S4','sql-group','S1','S2','S3','S5','S7','S10','sql-aggregate','sql-co-ban'],
 'Bạn hay nhầm khi nào dùng WHERE, khi nào dùng HAVING, và chọn thêm cột không có trong GROUP BY.',
 [S('SQL xử lí theo một thứ tự khác với thứ tự viết',['Dù bạn viết SELECT đầu tiên, máy xử lí theo thứ tự: FROM/JOIN (lấy bảng) → WHERE (lọc dòng) → GROUP BY (gom nhóm) → HAVING (lọc nhóm) → SELECT → ORDER BY.','Vì thế lúc WHERE chạy, các nhóm và hàm tổng hợp CHƯA tồn tại.'],'sql_pipeline'),
  S('GROUP BY: nhiều dòng thành một dòng cho mỗi nhóm',['Với bảng HocSinh(Ten, Lop), GROUP BY Lop gom các dòng cùng lớp lại, rồi hàm tổng hợp COUNT(*) đếm số dòng của mỗi nhóm.','Trong SELECT chỉ được đặt: cột có trong GROUP BY, hoặc hàm tổng hợp (COUNT, SUM, AVG, MAX, MIN).'],'sql_group'),
  S('WHERE hay HAVING?',['Điều kiện về từng DÒNG (Lop = "12A1", Diem >= 5) → WHERE, viết trước GROUP BY.','Điều kiện về cả NHÓM, có hàm tổng hợp (COUNT(*) > 2, AVG(Diem) >= 8) → HAVING, viết sau GROUP BY.'],None,'SELECT Lop, COUNT(*) AS SiSo\nFROM HocSinh\nWHERE Gioi = "Nữ"          -- lọc dòng trước\nGROUP BY Lop\nHAVING COUNT(*) > 2;        -- lọc nhóm sau',False,'sql'),
  S('Cẩn thận với COUNT',['COUNT(*) đếm số dòng; COUNT(cột) bỏ qua giá trị NULL; COUNT(DISTINCT cột) đếm số giá trị khác nhau. Muốn hỏi "có bao nhiêu học sinh khác nhau" hãy dùng DISTINCT.'],None)],
 [['WHERE COUNT(*) > 2.','Hàm tổng hợp phải đặt trong HAVING.'],['SELECT Ten, COUNT(*) … GROUP BY Lop.','Ten không nằm trong GROUP BY và không có hàm tổng hợp: không hợp lệ.'],['HAVING viết trước GROUP BY.','Thứ tự viết: WHERE → GROUP BY → HAVING → ORDER BY.']],
 'Câu hỏi mẹo: "điều kiện này nói về một dòng hay về cả nhóm?" Dòng → WHERE, nhóm → HAVING.')
lesson('sql_join','SQL: liên kết bảng và tìm "chưa có"',['sql-join'],
 'Bạn hay nhầm INNER JOIN với LEFT JOIN, và viết = NULL khi tìm đối tượng chưa xuất hiện.',
 [S('INNER JOIN và LEFT JOIN',['INNER JOIN chỉ giữ những dòng khớp ở CẢ HAI bảng. LEFT JOIN giữ MỌI dòng bảng bên trái; dòng không khớp có giá trị NULL ở các cột của bảng phải.','Điều kiện nối thường là khoá ngoài = khoá chính (ON Sach.MaSach = MuonSach.MaSach).'],'sql_join'),
  S('Bài toán "chưa từng…"',['Muốn tìm "sách chưa ai mượn": LEFT JOIN từ Sach sang MuonSach, rồi giữ các dòng có cột của MuonSach là NULL.','Phải viết IS NULL. So sánh = NULL không bao giờ đúng, vì NULL nghĩa là "không biết".'],None,'SELECT s.TenSach\nFROM Sach s LEFT JOIN MuonSach m ON s.MaSach = m.MaSach\nWHERE m.MaSach IS NULL;',False,'sql'),
  S('Cách khác: NOT IN',['Có thể viết: WHERE MaSach NOT IN (SELECT MaSach FROM MuonSach). Cách này dễ đọc nhưng cần chắc rằng truy vấn con không chứa NULL.'],None)],
 [['INNER JOIN vẫn giữ sách chưa ai mượn.','INNER JOIN bỏ các dòng không khớp.'],['WHERE m.MaSach = NULL.','Phải là IS NULL.'],['Đặt điều kiện IS NULL trên cột của bảng trái.','Phải lọc trên cột của bảng PHẢI (bảng bị thiếu).']],
 'Khi đề nói "chưa", "không có", "không bao giờ" → nghĩ ngay LEFT JOIN + IS NULL.')
lesson('sql_sub','SQL: truy vấn con và "cao nhất trong phạm vi"',['sql-subquery','S6'],
 'Bạn hay lấy MAX của toàn bảng thay vì MAX trong cùng phạm vi lọc, hoặc dùng MAX trực tiếp trong WHERE.',
 [S('Truy vấn con là một câu SELECT nằm trong ngoặc',['Truy vấn con tính ra một giá trị (hoặc một tập giá trị) rồi truy vấn ngoài dùng nó để so sánh: = , > với một giá trị; IN, NOT IN với nhiều giá trị.'],None),
  S('Cùng phạm vi lọc',['"Học sinh có điểm Tin cao nhất" → điểm cao nhất của MÔN TIN, không phải điểm cao nhất của cả bảng (có thể thuộc môn khác).','Điều kiện lọc của truy vấn con phải giống điều kiện của truy vấn ngoài (cùng môn, cùng lớp, cùng năm học…).'],None,'SELECT MaHS, Diem\nFROM KQ\nWHERE Mon = "Tin"\n  AND Diem = (SELECT MAX(Diem) FROM KQ WHERE Mon = "Tin");',False,'sql'),
  S('Vì sao không viết WHERE Diem = MAX(Diem)?',['Hàm tổng hợp chưa tồn tại lúc WHERE chạy (xem thứ tự xử lí). Phải dùng truy vấn con, hoặc ORDER BY Diem DESC LIMIT 1 (nhưng chỉ lấy một người, bỏ sót đồng hạng).','Dùng = với MAX sẽ trả về mọi học sinh đồng điểm cao nhất.'],None)],
 [['Bỏ điều kiện môn trong truy vấn con.','MAX toàn bảng có thể không thuộc môn đang xét → kết quả rỗng hoặc sai.'],['WHERE Diem = MAX(Diem).','Dùng truy vấn con.'],['LIMIT 1 luôn đúng.','Bỏ sót các học sinh đồng hạng.']],
 'Truy vấn con "kế thừa" cùng WHERE với truy vấn ngoài: hãy chép điều kiện sang.')
lesson('csdl_key','CSDL: khoá chính, khoá ngoài, ràng buộc',['csdl-khoa','S9','sql-rangbuoc','csdl-kieu','S8'],
 'Bạn hay nhầm vai trò của khoá ngoài, hoặc không biết vì sao thêm hay xoá một dòng bị từ chối.',
 [S('Hai loại khoá',['Khoá chính: xác định duy nhất mỗi bản ghi, không được trống, không được trùng; có thể gồm nhiều trường.','Khoá ngoài: trường của bảng này tham chiếu tới khoá chính của bảng khác, tạo liên kết giữa hai bảng. Giá trị khoá ngoài có thể trùng nhau.'],'csdl_khoa'),
  S('Ràng buộc toàn vẹn tham chiếu',['Không thể THÊM học sinh có MaLop chưa tồn tại trong bảng Lop. Không thể XOÁ lớp khi còn học sinh tham chiếu tới nó (mặc định).','Đó là cách hệ quản trị bảo đảm dữ liệu luôn nhất quán.'],None),
  S('UPDATE và DELETE cẩn thận',['UPDATE/DELETE không có WHERE sẽ tác động lên TẤT CẢ các dòng. Hãy thử bằng SELECT với cùng điều kiện WHERE trước khi chạy.'],None,'UPDATE LuotThue SET SoGio = SoGio + 1 WHERE MaKT = "K001";',False,'sql'),
  S('Chọn kiểu dữ liệu',['Số điện thoại, mã vạch là định danh → kiểu xâu để giữ số 0 đầu. Điểm, giá tiền → kiểu số để so sánh và tính trung bình. Ngày tháng → DATE.','Nếu lưu số bằng xâu thì "10" đứng trước "9" khi sắp xếp.'],None)],
 [['Khoá ngoài xác định duy nhất bản ghi.','Đó là khoá chính.'],['Có thể thêm dòng con với khoá ngoài chưa có ở bảng cha.','Bị từ chối bởi ràng buộc toàn vẹn.'],['Lưu số điện thoại kiểu số nguyên.','Dùng xâu để giữ số 0 đầu.']],
 'Nhớ: khoá chính để NHẬN DIỆN, khoá ngoài để NỐI.')
# ================= PYTHON / THUẬT TOÁN =================
lesson('complexity','Đánh giá độ phức tạp thời gian',['do-phuc-tap'],
 'Bạn hay thấy hai vòng for lồng nhau là kết luận O(n²) mà không xem vòng trong thật sự chạy bao nhiêu lần.',
 [S('Độ phức tạp là gì?',['Là cách số phép toán cơ bản tăng lên khi kích thước dữ liệu n tăng. Ta bỏ hệ số hằng và các số hạng bậc thấp: 3n² + 5n + 7 → O(n²).','Các mức hay gặp, từ nhanh đến chậm: O(1), O(log n), O(n), O(n log n), O(n²), O(2ⁿ).'],'complexity'),
  S('Cách đếm vòng lặp',['Vòng đơn chạy n lần → O(n). Hai vòng lồng: nhân số lần, NHƯNG phải xem vòng trong chạy bao nhiêu lần (hằng số, n, hay phụ thuộc i).','Biến lặp nhân/chia đôi (i *= 2) → O(log n). Hai khối nối tiếp → cộng rồi lấy số hạng lớn nhất.'],None),
  S('Ví dụ vòng lồng "lệch"',['Vòng trong nhảy bước i nên chạy khoảng n/i lần. Hãy đếm bằng tay với n = 8 rồi kiểm tra bằng máy.'],'loops','ops = 0\nfor i in range(1, 8):\n    j = i\n    while j < 8:\n        ops += 1\n        j += i\nprint(ops)',True,'py'),
  S('Kết luận',['Tổng ≈ n(1 + 1/2 + 1/3 + …) ≈ n·ln n nên độ phức tạp là O(n log n), nhỏ hơn nhiều so với O(n²).','Khi n = 100 000: log n ≈ 17, n² = 10 tỉ — chênh lệch rất lớn.'],None)],
 [['Hai vòng lồng nhau → luôn O(n²).','Phải xem vòng trong chạy mấy lần.'],['O(n log n) lúc nào cũng nhanh hơn O(n²).','Chỉ đúng khi n đủ lớn; O chỉ nói về tốc độ tăng.'],['i *= 2 là O(n).','Là O(log n).']],
 'Hãy đếm thật với n nhỏ (n = 8) rồi nhận ra quy luật.')
lesson('search','Tìm kiếm tuần tự và nhị phân',['tim-kiem'],
 'Bạn hay dùng tìm nhị phân cho dãy chưa sắp xếp, hoặc đếm sai số lần so sánh.',
 [S('Hai cách tìm',['Tuần tự: duyệt từng phần tử, O(n), dùng được với mọi dãy. Trung bình khoảng (n+1)/2 phép so sánh.','Nhị phân: CHỈ dùng khi dãy đã sắp xếp. Mỗi lần so sánh với phần tử giữa, bỏ đi một nửa miền tìm: tối đa ⌊log₂ n⌋ + 1 lần.'],'bsearch'),
  S('Chạy từng bước',['Dãy 15 số, tìm 23: m = (l + r)//2. Lần 1 m = 7 (56 > 23 → r = m − 1); lần 2 m = 3 (12 < 23 → l = m + 1); lần 3 m = 5 → trúng.'],None,'a = [2, 5, 8, 12, 16, 23, 38, 56, 72, 91, 95, 99, 104, 110, 120]\nl, r, dem = 0, len(a) - 1, 0\nwhile l <= r:\n    m = (l + r) // 2\n    dem += 1\n    if a[m] == 23:\n        break\n    if a[m] < 23:\n        l = m + 1\n    else:\n        r = m - 1\nprint(m, dem)',True,'py'),
  S('Hai lỗi hay gặp',['Điều kiện lặp phải là l <= r (không phải l < r), nếu không sẽ bỏ sót trường hợp còn đúng một phần tử.','Cập nhật phải là l = m + 1 hoặc r = m − 1; viết l = m dễ gây lặp vô hạn.'],None)],
 [['Nhị phân dùng được cho dãy bất kì.','Phải sắp xếp trước.'],['n = 100 000 cần 50 000 lần so sánh.','Chỉ tối đa 17 lần.'],['Viết while l < r.','Phải là l <= r.']],
 'Nhị phân = "đoán số": mỗi lần đoán số giữa rồi loại một nửa.')
lesson('sort','Sắp xếp chọn, chèn, nổi bọt',['sap-xep','thuat-toan'],
 'Bạn hay nhầm ba thuật toán với nhau và suy diễn sai trạng thái sau k lượt.',
 [S('Sắp xếp chọn',['Mỗi lượt tìm số NHỎ NHẤT của phần chưa sắp xếp rồi đổi chỗ với phần tử đầu phần đó. Luôn n(n−1)/2 phép so sánh, tối đa n−1 lần đổi chỗ.'],'ssort','a = [29, 10, 14, 37, 13]\nfor i in range(2):\n    m = min(range(i, len(a)), key=lambda j: a[j])\n    a[i], a[m] = a[m], a[i]\nprint(a)',True,'py'),
  S('Sắp xếp chèn',['Lấy phần tử a[i], dịch các phần tử lớn hơn nó sang phải rồi chèn vào chỗ trống. Tốt nhất O(n) (dãy đã sắp xếp), xấu nhất O(n²). Ổn định.'],None),
  S('Sắp xếp nổi bọt',['So sánh cặp kề nhau, đổi chỗ nếu sai thứ tự; số lớn dần "nổi" về cuối. Nếu một lượt không đổi chỗ nào thì dừng (nên dãy đã sắp xếp chỉ tốn 1 lượt). Ổn định.'],None),
  S('Nhận diện nhanh trong đoạn mã',['Tìm phần tử nhỏ nhất rồi đổi chỗ → chọn. Dịch các phần tử sang phải rồi chèn → chèn. So sánh a[j] và a[j+1] → nổi bọt. Khi đề cho trạng thái "sau k lượt", hãy vẽ lại từng lượt, đừng suy diễn từ kết quả cuối.'],None)],
 [['Sắp xếp chọn nhanh khi dãy đã sắp xếp.','Vẫn n² phép so sánh.'],['Chọn và chèn giống nhau.','Chọn đổi chỗ xa; chèn dịch chuyển.'],['Bỏ qua việc vẽ từng lượt.','Hãy ghi lại mảng sau mỗi lượt.']],
 'Nhớ: Chọn = "chọn nhỏ nhất", Chèn = "chèn vào chỗ", Nổi bọt = "so cặp kề".')
lesson('recursion','Đệ quy: điều kiện dừng, số lần gọi',['de-quy'],
 'Bạn hay đếm sai số lần gọi, hoặc không thấy vì sao đệ quy chậm.',
 [S('Hai thành phần bắt buộc',['Điều kiện dừng (trường hợp cơ sở) và bước thu nhỏ bài toán. Thiếu một trong hai thì chạy vô hạn → RecursionError.'],None),
  S('Vẽ cây lời gọi',['Với f(n) = f(n−1) + f(n−2), f(0) = f(1) = 1. Mỗi f(n) gọi hai hàm con. Hãy vẽ cây rồi đếm các nút (mỗi nút là một lời gọi).'],'recursion','dem = 0\ndef f(n):\n    global dem\n    dem += 1\n    return 1 if n <= 1 else f(n - 1) + f(n - 2)\nf(6)\nprint(dem)',True,'py'),
  S('Công thức đếm',['C(n) = 1 + C(n−1) + C(n−2), với C(0) = C(1) = 1: C(2) = 3, C(3) = 5, C(4) = 9, C(5) = 15, C(6) = 25.','Hai lời gọi con cỡ n−1 → O(2ⁿ) vì cùng một giá trị bị tính lặp lại. Dùng bộ nhớ (memo) sẽ giảm xuống O(n).'],None),
  S('Cách đoán độ phức tạp',['Một lời gọi con cỡ n−1 → O(n). Một lời gọi cỡ n/2 → O(log n). Hai lời gọi cỡ n/2 và việc ghép tốn n → O(n log n). Độ sâu đệ quy cũng tốn bộ nhớ ngăn xếp.'],None)],
 [['Quên tính lời gọi đầu tiên.','Số nút của cây = số lời gọi.'],['Nhầm giá trị trả về với số lần gọi.','Đây là hai đại lượng khác nhau.'],['Cho rằng đệ quy luôn O(n).','Hai nhánh con → O(2ⁿ).']],
 'Gặp bài đệ quy: vẽ cây nhỏ (n = 4) rồi mới tính.')
lesson('strings','Xâu và danh sách: cắt lát, sao chép',['xau-danh-sach','xau'],
 'Bạn hay đếm lệch chỉ số khi cắt lát, và tưởng b = a là sao chép.',
 [S('Chỉ số dương và âm',['Chỉ số dương đếm từ 0 từ đầu; chỉ số âm đếm từ cuối (−1 là phần tử cuối). Lát cắt s[a:b] lấy từ a đến TRƯỚC b; s[a:b:c] có bước c; s[::-1] đảo ngược.'],'slice','s = "TinHoc11"\nprint(s[::-1], s[1::2], s[1:-1:2], s.find("Hoc"))',True,'py'),
  S('Khả biến và bất biến',['Danh sách (list) khả biến: b = a chỉ tạo thêm một "tên" cho cùng một danh sách, nên sửa b là sửa a. a[:] hoặc a.copy() mới tạo bản sao (nông).','Xâu (str) bất biến: s.upper() trả về xâu MỚI, s không đổi.'],None,'a = [5, 2, 8]\nb = a\nc = a[:]\nb.append(7)\nprint(a, c)',True,'py'),
  S('Phương thức hay gặp',['split() không tham số tách theo mọi dãy khoảng trắng; split(" ") tách tại từng dấu cách và sinh xâu rỗng nếu có hai dấu cách liền nhau.'],None)],
 [['Lát cắt lấy cả chỉ số b.','Dừng TRƯỚC b.'],['b = a là sao chép.','Là cùng một đối tượng.'],['s.upper() thay đổi s.','s bất biến, kết quả là xâu mới.']],
 'Vẽ thước chỉ số 0, 1, 2… phía trên và −n…−1 phía dưới như hình, rồi tô các ô được chọn.')
lesson('matrix','Mảng hai chiều (ma trận)',['mang-2d'],
 'Bạn hay nhầm chỉ số hàng với cột, và không biết vì sao [[0]*3]*3 gây lỗi lạ.',
 [S('a[i][j]: hàng i, cột j',['Ma trận n × m có n hàng và m cột, chỉ số từ 0. Đường chéo chính có i = j; đường chéo phụ có i + j = n − 1.'],'matrix'),
  S('Bẫy khi tạo ma trận',['[[0]*3]*3 tạo ra ba tham chiếu tới CÙNG MỘT danh sách hàng, nên sửa một hàng là cả ba hàng cùng đổi. Cách đúng: [[0]*3 for _ in range(3)].'],None,'a = [[0] * 3] * 3\na[0][1] = 5\nprint(a)\nb = [[0] * 3 for _ in range(3)]\nb[0][1] = 5\nprint(b)',True,'py'),
  S('Chuyển vị',['t[j][i] = a[i][j]: vòng ngoài chạy theo cột của a, vòng trong chạy theo hàng.'],None)],
 [['Tạo ma trận bằng phép nhân danh sách lồng.','Dùng danh sách sinh (list comprehension).'],['Đường chéo phụ là i + j = n.','Là i + j = n − 1 (chỉ số từ 0).']],
 'Nhớ: hàng trước, cột sau — a[hàng][cột].')
lesson('scope','Hàm, phạm vi biến, tham số mặc định',['ham-pham-vi'],
 'Bạn hay nhầm khi nào biến trong hàm là biến mới, khi nào là biến toàn cục.',
 [S('Cục bộ và toàn cục',['Gán giá trị cho một biến BÊN TRONG hàm tạo ra biến cục bộ mới (che biến toàn cục cùng tên). Muốn sửa biến toàn cục phải khai báo global.'],'scope','x = 7\ndef g():\n    x = 3\n    return x * 2\ndef h():\n    global x\n    x = x + 1\ny = g()\nh()\nprint(x, y)',True,'py'),
  S('Thiếu global',['Nếu bỏ dòng global x trong h(), Python hiểu x là biến cục bộ nhưng lại dùng nó trước khi gán → UnboundLocalError.'],None),
  S('Tham số mặc định chỉ được tạo một lần',['def them(x, ds=[]) dùng chung MỘT danh sách cho mọi lần gọi. Cách an toàn: ds=None rồi tạo danh sách mới bên trong.'],None,'def them(x, ds=[]):\n    ds.append(x)\n    return ds\nprint(them(1), them(2))',True,'py')],
 [['Gán trong hàm là sửa biến toàn cục.','Gán tạo biến cục bộ.'],['Danh sách mặc định mới được tạo mỗi lần gọi.','Chỉ tạo một lần.']],
 'Đọc code: thấy phép gán trong hàm thì tự hỏi "có global không?"')
lesson('ds','Ngăn xếp (LIFO) và hàng đợi (FIFO)',['cau-truc-du-lieu','ctdl'],
 'Bạn hay nhầm thứ tự lấy ra, và không biết vì sao list.pop(0) chậm.',
 [S('Hai cấu trúc',['Ngăn xếp: vào sau – ra trước (LIFO), thao tác ở một đầu: append / pop. Hàng đợi: vào trước – ra trước (FIFO): thêm ở cuối, lấy ở đầu.'],'stackqueue'),
  S('Ví dụ ngoặc cân bằng',['Duyệt xâu: gặp ngoặc mở thì đẩy vào ngăn xếp; gặp ngoặc đóng thì lấy ngoặc mở trên đỉnh ra so khớp. Xâu "([)]" sai vì khi gặp ")" đỉnh là "[".'],None),
  S('Chi phí',['list.append và list.pop() ở cuối: O(1). list.pop(0) phải dịch cả danh sách: O(n). Hàng đợi dùng collections.deque với popleft() O(1). pop() trên danh sách rỗng gây IndexError.'],None)],
 [['Nhầm LIFO với FIFO.','Ngăn xếp: lấy phần tử vào sau cùng.'],['Dùng list.pop(0) cho hàng đợi lớn.','Dùng deque.']],
 'Ngăn xếp như chồng đĩa, hàng đợi như xếp hàng mua vé.')
